 412	func (r *oq3Run) terminalTurn(i int, st oq3Step, label string) {
 413		if r.termRefusedAtStart && r.term.hasExited() {
 414			// The session refused at start-up and has ended: nothing can be typed, and no request under
 415			// this step was sent. Scored by the step's class (a refusal held as required).
 416			r.event(i, st, "no-request", map[string]any{"session": "refused at start-up; the process has exited"})
 417			return
 418		}
 419		rounds, _ := strconv.Atoi(st.Args["tool_rounds"])
 420		if rounds > 0 {
 421			r.d.setToolRounds(label, rounds)
 422		}
 423		if st.Args["auto_compact"] == "1" {
 424			r.d.reportPromptEval(label, 30000)
 425		}
 426		mark := r.term.rawLen()
 427		if st.Args["hold"] == "1" {
 428			r.d.hold(label)
 429			r.marksLabel["terminal"] = label
 430			r.marks["terminal"] = mark
 431		}
 432		r.term.typeLine(st.Prompt)
 433		if !oq3WaitFor(30*time.Second, func() bool { return r.d.countLabel("POST", "/api/chat", label) >= 1 }) {
 434			// No request reached the daemon: recorded, and scored by the step's class (a missing
 435			// required delivery, or a refusal held as required).
 436			r.mustIdle("after a turn that sent no request")
 437			r.event(i, st, "no-request", map[string]any{"screen_tail": tail(r.term.screen(), 1200)})
 438			return
 439		}
 440		if st.Args["hold"] == "1" {
 441			r.marks["terminal-rounds"] = rounds
 442			r.event(i, st, "dispatched-held", nil)
 443			return
 444		}
 445		r.finishTerminalTurn(label, rounds, st.Summarisers, mark)
 446		r.event(i, st, "done", nil)
 447	}
 448	
 449	// finishTerminalTurn approves each declared tool round, then waits until every response under the
 450	// label has been fully written by the daemon (review finding 8) and the chat has proved it is idle
 451	// (review round 2, finding 5): the daemon finishing and the screen going quiet do not show that the
 452	// chat's run has ended.
 453	func (r *oq3Run) finishTerminalTurn(label string, rounds, summarisers, mark int) {
 454		for k := 0; k < rounds; k++ {
 455			approvalMark := mark
 456			if !oq3WaitFor(30*time.Second, func() bool { return r.term.screenContainsAfter(approvalMark, "Approve once") }) {
 457				r.harnessFail("tool round %d: approval prompt never appeared; screen tail %q", k+1, tail(r.term.screen(), 1500))
 458			}
 459			want := r.d.countLabel("POST", "/api/chat", label) + 1
 460			mark = r.term.rawLen()
 461			r.term.key("1")
 462			if !oq3WaitFor(30*time.Second, func() bool { return r.d.countLabel("POST", "/api/chat", label) >= want }) {
 463				r.harnessFail("tool round %d: continuation never reached the daemon", k+1)
 464			}
 465		}
 466		if !oq3WaitFor(30*time.Second, func() bool {
 467			n := r.d.countLabel("POST", "/api/chat", label)
 468			return r.d.countSummaries(label) >= summarisers && r.d.completedLabel(label) >= n
 469		}) {
 470			r.harnessFail("responses under %s never completed (%d requests, %d completed, %d summaries)", label,
 471				r.d.countLabel("POST", "/api/chat", label), r.d.completedLabel(label), r.d.countSummaries(label))
 472		}
 473		r.mustIdle("after the turn completed")
 474	}
 475	
 476	// mustQuiet waits for the terminal to stop producing output; a timeout is a harness failure, never
 477	// a reason to advance (review finding 8). It paces keystrokes into a menu or picker; it is not the
 478	// proof that a turn has ended, which is mustIdle.
 479	func (r *oq3Run) mustQuiet(when string) {
 480		if !r.term.quiet(600*time.Millisecond, 20*time.Second) {
 481			r.harnessFail("terminal did not go quiet %s; screen tail %q", when, tail(r.term.screen(), 800))
 482		}
 483	}
 484	
 485	// mustIdle requires the chat's own proof that it is idle (oq3Terminal.idle); a timeout is a harness
 486	// failure, never a reason to advance (review round 2, finding 5).
 487	func (r *oq3Run) mustIdle(when string) {
 488		if !r.term.idle(30 * time.Second) {
 489			r.harnessFail("terminal never proved idle %s; screen tail %q", when, tail(r.term.screen(), 800))
 490		}
 491	}
