 545	// ---------------------------------------------------------------------------------------------
 546	// Operation verdicts. "absent" means the designated surface does not exist at this commit (the
 547	// application's HTML fallback or an unknown command); it is a failed operation, not a harness fault.
 548	
 549	func oq3IsHTML(res oq3HTTPResult) bool {
 550		return strings.Contains(strings.ToLower(res.ContentType), "text/html") || strings.HasPrefix(strings.TrimSpace(strings.ToLower(res.Body)), "<!doctype html")
 551	}
 552	
 553	func oq3ProfileVerdict(res oq3HTTPResult, want map[string]string) string {
 554		if oq3IsHTML(res) || res.Status == http.StatusNotFound {
 555			return "absent"
 556		}
 557		var p struct {
 558			Revision string `json:"revision"`
 559			Enabled  bool   `json:"enabled"`
