 759	// decoded and scanned in turn, so an escape such as \u0053 cannot hide text; a body that is not JSON
 760	// is scanned as text. Encodings other than JSON's (base64, for example) are not decoded.
 761	func oq3BodyLeaks(c oq3Capture) []string {
 762		var out []string
 763		if len(c.Body) > 0 {
 764			var walk func(v any, depth int)
 765			scanString := func(s string, depth int) {
 766				out = append(out, oq3Leaks(s)...)
 767				if depth < 4 {
 768					if t := strings.TrimSpace(s); (strings.HasPrefix(t, "{") || strings.HasPrefix(t, "[") || strings.HasPrefix(t, `"`)) && json.Valid([]byte(t)) {
 769						var inner any
 770						if json.Unmarshal([]byte(t), &inner) == nil {
 771							walk(inner, depth+1)
 772						}
 773					}
 774				}
 775			}
 776			walk = func(v any, depth int) {
 777				switch x := v.(type) {
 778				case map[string]any:
 779					for k, val := range x {
 780						scanString(k, depth)
 781						walk(val, depth)
 782					}
 783				case []any:
 784					for _, val := range x {
 785						walk(val, depth)
 786					}
 787				case string:
 788					scanString(x, depth)
 789				}
 790			}
 791			var v any
 792			if json.Unmarshal(c.Body, &v) == nil {
 793				walk(v, 0)
 794			} else {
 795				out = append(out, oq3Leaks(string(c.Body))...)
 796			}
 797		}
 798		if c.RawBody != "" {
 799			out = append(out, oq3Leaks(c.RawBody)...)
 800		}
 801		return out
 802	}
