 827	func oq3Dedupe(xs []string) []string {
 828		seen := map[string]bool{}
 829		var out []string
 830		for _, x := range xs {
 831			if !seen[x] {
 832				seen[x] = true
 833				out = append(out, x)
 834			}
 835		}
 836		sort.Strings(out)
 837		return out
 838	}
