  1377	func renderFooterPlainLine(line string) string {
  1378		const fullAccess = "full access"
  1379		if !strings.Contains(line, fullAccess) {
  1380			return chatFooterStyle.Render(line)
  1381		}
  1382	
  1383		var b strings.Builder
  1384		for {
  1385			before, after, ok := strings.Cut(line, fullAccess)
  1386			if before != "" {
  1387				b.WriteString(chatFooterStyle.Render(before))
  1388			}
  1389			if !ok {
  1390				break
  1391			}
  1392			b.WriteString(chatFullAccessStyle.Render(fullAccess))
  1393			line = after
  1394		}
  1395		return b.String()
  1396	}
