1477	func (m chatModel) activityLabel() string {
1478		if m.status == "canceling" {
1479			return "canceling"
1480		}
1481		if m.compacting {
1482			if m.compactingTokens > 0 {
1483				return "Compacting " + formatTokenCount(m.compactingTokens)
1484			}
1485			return "Compacting"
1486		}
1487		if m.thinking {
1488			return thinkingActivityLabel(m.thinkingTokens)
1489		}
1490		start := m.currentTurnEntryStart()
1491		for i := len(m.entries) - 1; i >= start; i-- {
1492			entry := m.entries[i]
1493			switch entry.role {
1494			case "tool":
1495				if isToolActiveStatus(entry.status) {
1496					return ""
1497				}
1498			case "tool_group":
1499				if entryHasActiveTool(entry) {
1500					return ""
