   572	func (d *oq3Daemon) serveChat(w http.ResponseWriter, r *http.Request, body []byte) {
   573		var req struct {
   574			Model    string `json:"model"`
   575			Messages []struct {
   576				Role    string `json:"role"`
   577				Content string `json:"content"`
   578			} `json:"messages"`
   579			Admission json.RawMessage `json:"admission"`
   580		}
   581		_ = json.Unmarshal(body, &req)
   582		d.mu.Lock()
   583		label := d.label
   584		hold := d.holds[label]
   585		failStatus := d.fails[label]
   586		promptEval := d.promptEval[label]
   587		rounds, done := d.toolRounds[label], d.toolsDone[label]
   588		d.mu.Unlock()
   589	
   590		// The response is chosen from the request's shape and the label's declared behaviour, never
   591		// from whether the request carries instructions.
   592		kind := "reply"
   593		n := len(req.Messages)
   594		switch {
   595		case n > 0 && req.Messages[0].Role == "system" && strings.HasPrefix(req.Messages[0].Content, oq3CompactionSystemPrefix):
   596			kind = "summary"
   597		case failStatus != 0:
   598			kind = "injected-failure"
   599		case n > 0 && req.Messages[n-1].Role == "user" && strings.Contains(req.Messages[n-1].Content, oq3ToolTrigger) && rounds > 0 && done == 0:
   600			kind = "toolcall"
   601		case n > 0 && req.Messages[n-1].Role == "tool" && done > 0 && done < rounds:
   602			kind = "toolcall"
   603		}
   604		d.record(r, body, kind)
   605		if kind == "toolcall" {
   606			d.mu.Lock()
   607			d.toolsDone[label]++
   608			call := d.toolsDone[label]
   609			d.mu.Unlock()
   610			kind = fmt.Sprintf("toolcall-%d", call)
   611		}
   612		if hold != nil {
   613			select {
   614			case <-hold:
   615			case <-r.Context().Done():
   616				return
   617			}
   618		}
   619		if failStatus != 0 {
   620			d.mu.Lock()
   621			delete(d.fails, label)
   622			d.mu.Unlock()
   623			w.Header().Set("Content-Type", "application/json")
   624			w.WriteHeader(failStatus)
   625			io.WriteString(w, `{"error":"oq3 fake daemon: injected failure"}`)
   626			d.markCompleted(label)
   627			return
   628		}
   629		defer d.markCompleted(label)
   630		model := req.Model
   631		if model == "" {
   632			model = oq3Model
   633		}
   634		w.Header().Set("Content-Type", "application/x-ndjson")
   635		enc := json.NewEncoder(w)
   636		now := "2026-09-26T00:00:00Z"
   637		switch {
   638		case kind == "summary":
   639			enc.Encode(map[string]any{"model": model, "created_at": now, "message": map[string]any{"role": "assistant", "content": "OQ3-SUMMARY: earlier turns were exchanged."}, "done": false})
   640		case strings.HasPrefix(kind, "toolcall-"):
   641			enc.Encode(map[string]any{"model": model, "created_at": now, "message": map[string]any{"role": "assistant", "content": "", "tool_calls": []any{map[string]any{"id": "call_oq3_" + strings.TrimPrefix(kind, "toolcall-"), "function": map[string]any{"name": "read", "arguments": map[string]any{"path": oq3FixtureFile}}}}}, "done": false})
   642		default:
   643			enc.Encode(map[string]any{"model": model, "created_at": now, "message": map[string]any{"role": "assistant", "content": d.nextReply()}, "done": false})
   644		}
   645		final := map[string]any{"model": model, "created_at": now, "message": map[string]any{"role": "assistant", "content": ""}, "done": true, "done_reason": "stop", "prompt_eval_count": 10, "eval_count": 3}
   646		if promptEval > 0 {
   647			final["prompt_eval_count"] = promptEval
   648		}
   649		if len(req.Admission) > 0 && string(req.Admission) != "null" {
   650			// Blueprint §6.3 A9: the final record of an admitted request carries its diagnostics.
   651			final["admission"] = map[string]any{"version": 1, "route": "local", "context_length": 32768, "reserve": 4096, "dropped_messages": 0, "context_exhausted": false}
   652		}
   653		enc.Encode(final)
   654	}
