   880	// oq3StartTerminalWith starts either a helper (argv nil; helperMode "terminal" is the launch function,
   881	// the other modes are runner controls) or a given program (the built binary for the entry arm) on a
   882	// fresh pseudo-terminal.
   883	func oq3StartTerminalWith(fail oq3Fail, s *oq3Sandbox, d *oq3Daemon, session, model string, argv []string, helperMode string) *oq3Terminal {
   884		master, slave, err := oq3OpenPTY()
   885		if err != nil {
   886			fail("pty: %v", err)
   887		}
   888		var c *exec.Cmd
   889		if argv == nil {
   890			c = oq3HelperCmd(s, d, helperMode, "OQ3_MODEL="+model)
   891		} else {
   892			c = exec.Command(argv[0], argv[1:]...)
   893			c.Dir = s.work
   894			c.Env = s.env(d.srv.URL)
   895		}
   896		c.Stdin, c.Stdout, c.Stderr = slave, slave, slave
   897		c.SysProcAttr = &syscall.SysProcAttr{Setsid: true, Setctty: true, Ctty: 0}
   898		if err := c.Start(); err != nil {
   899			fail("start terminal: %v", err)
   900		}
   901		slave.Close()
   902		p := &oq3Terminal{fail: fail, cmd: c, master: master, exited: make(chan error, 1)}
   903		go p.readLoop(filepath.Join(s.logs, "terminal-"+session+".raw"))
   904		go func() {
   905			err := c.Wait()
   906			p.mu.Lock()
   907			p.gone = true
   908			p.mu.Unlock()
   909			p.exited <- err
   910		}()
   911		return p
   912	}
