   951	// readLoop keeps the transcript and answers the terminal queries a real emulator would answer
   952	// (background colour, foreground colour, cursor position, device attributes).
   953	func (p *oq3Terminal) readLoop(rawPath string) {
   954		f, _ := os.Create(rawPath)
   955		defer func() {
   956			if f != nil {
   957				f.Close()
   958			}
   959		}()
   960		buf := make([]byte, 64*1024)
   961		for {
   962			n, err := p.master.Read(buf)
   963			if n > 0 {
   964				chunk := buf[:n]
   965				if f != nil {
   966					f.Write(chunk)
   967				}
   968				p.mu.Lock()
   969				p.raw.Write(chunk)
   970				p.mu.Unlock()
   971				s := string(chunk)
   972				if strings.Contains(s, "\x1b]11;?") {
   973					p.master.Write([]byte("\x1b]11;rgb:1c1c/1c1c/1c1c\x1b\\"))
   974				}
   975				if strings.Contains(s, "\x1b]10;?") {
   976					p.master.Write([]byte("\x1b]10;rgb:e0e0/e0e0/e0e0\x1b\\"))
   977				}
   978				if strings.Contains(s, "\x1b[6n") {
   979					p.master.Write([]byte("\x1b[1;1R"))
   980				}
   981				if strings.Contains(s, "\x1b[c") || strings.Contains(s, "\x1b[0c") {
   982					p.master.Write([]byte("\x1b[?62;22c"))
   983				}
   984			}
   985			if err != nil {
   986				return
   987			}
   988		}
   989	}
