1165	// scoreDeliveriesOnly scores the requests captured under each dispatch step against that step's
1166	// expectations and the frozen goldens, without freezing and without the omission, summariser and
1167	// compaction checks. The reference arm uses it: it only re-sends requests that have a golden.
1168	func (r *oq3Run) scoreDeliveriesOnly(goldenDir string) oq3ScenarioResult {
1169		res := oq3ScenarioResult{Scenario: r.sc, Sandbox: r.s.root}
1170		caps := r.d.snapshot()
1171		res.Captures = caps
1172		for i, st := range r.sc.Steps {
1173			if st.Class != "required-dispatch" {
1174				continue
1175			}
1176			label := oq3Label(r.sc.ID, i, st.Op)
1177			k := 0
1178			for _, c := range caps {
1179				if c.Path != "/api/chat" || c.Label != label {
1180					continue
1181				}
1182				d := oq3Delivery{Scenario: r.sc.ID, Step: i, Label: label, Trial: st.Trial, Index: k, Seq: c.Seq}
1183				if k >= len(st.Expect) {
1184					d.Status, d.Verdict = "unexpected", oq3DeliveryVerdict{Categories: []string{"unexpected-request"}}
1185					res.Deliveries = append(res.Deliveries, d)
1186					k++
1187					continue
1188				}
1189				e := st.Expect[k]
1190				d.Expect = &e
1191				gp := oq3GoldenPath(goldenDir, r.sc.ID, i, k)
1192				d.Golden = gp
1193				k++
1194				obs, err := oq3Normalise(c.Body, r.s.root)
1195				if err != nil {
1196					d.Status, d.Verdict = "bad", oq3DeliveryVerdict{Categories: []string{"malformed-capture"}}
1197					res.Deliveries = append(res.Deliveries, d)
1198					continue
1199				}
1200				golden, err := oq3LoadGolden(gp)
1201				if err != nil {
1202					d.Status, d.Verdict = "bad", oq3DeliveryVerdict{Categories: []string{"no-golden"}}
1203					res.Deliveries = append(res.Deliveries, d)
1204					continue
1205				}
1206				exp, err := oq3Transform(golden, e, func(model string) (string, bool) {
1207					s, ok := r.d.modelSystems[oq3ModelBase(model)]
1208					return s, ok
1209				})
1210				if err != nil {
1211					d.Status, d.Verdict = "bad", oq3DeliveryVerdict{Categories: []string{"oracle-unresolved"}}
1212					res.Deliveries = append(res.Deliveries, d)
1213					continue
1214				}
1215				d.Verdict = oq3Score(obs, exp, e)
1216				d.Status = map[bool]string{true: "correct", false: "bad"}[d.Verdict.Correct]
1217				res.Deliveries = append(res.Deliveries, d)
1218			}
1219		}
1220		return res
1221	}
