1281	func oq3Summarise(results []oq3ScenarioResult, mode, source, ledgerSHA string) oq3Summary {
1282		s := oq3Summary{Mode: mode, Source: source, CategoryCounts: map[string]int{}, PerFamily: map[string]any{}, PerTrial: map[string]any{},
1283			OperationVerdicts: map[string]int{}, RefusalVerdicts: map[string]int{}, AuxiliaryChecks: map[string]int{}, LedgerSHA256: ledgerSHA, Valid: true}
1284		family := map[string]string{}
1285		type tally struct{ Observed, Bad, Missing, Correct int }
1286		trialT := map[string]*tally{}
1287		for _, r := range results {
1288			s.ScenariosRun = append(s.ScenariosRun, r.Scenario.ID)
1289			for _, tr := range r.Scenario.Trials {
1290				family[tr.ID] = tr.Family
1291				trialT[tr.ID] = &tally{}
1292				s.Trials++
1293			}
1294			for _, d := range r.Deliveries {
1295				t := trialT[d.Trial]
1296				switch d.Status {
1297				case "correct":
1298					s.ObservedDeliveries++
1299					t.Observed++
1300					t.Correct++
1301				case "bad":
1302					s.ObservedDeliveries++
1303					s.BadObserved++
1304					t.Observed++
1305					t.Bad++
1306				case "missing":
1307					s.MissingRequired++
1308					t.Missing++
1309				case "unexpected":
1310					s.ObservedDeliveries++
1311					s.Unexpected++
1312					s.BadObserved++
1313					t.Observed++
1314					t.Bad++
1315				case "refused-as-required":
