1342		}
1343		fam := map[string]*tally{}
1344		for id, t := range trialT {
1345			f := family[id]
1346			if fam[f] == nil {
1347				fam[f] = &tally{}
1348			}
1349			fam[f].Observed += t.Observed
1350			fam[f].Bad += t.Bad
1351			fam[f].Missing += t.Missing
1352			fam[f].Correct += t.Correct
1353			s.PerTrial[id] = map[string]any{"family": f, "observed": t.Observed, "correct": t.Correct, "bad": t.Bad, "missing": t.Missing}
1354		}
1355		famTrials := map[string]int{}
1356		for _, f := range family {
1357			famTrials[f]++
1358		}
1359		for f, t := range fam {
1360			s.PerFamily[f] = map[string]any{"trials": famTrials[f], "observed": t.Observed, "correct": t.Correct, "bad": t.Bad, "missing": t.Missing,
1361				"failure_number": oq3Ratio(t.Bad+t.Missing, famTrials[f])}
1362		}
1363		s.FailureNumerator = s.BadObserved + s.MissingRequired
1364		s.FailureNumber = oq3Ratio(s.FailureNumerator, s.Trials)
1365		return s
