+			}
+		}
+		walk = func(v any, depth int) {
+			switch x := v.(type) {
+			case map[string]any:
+				for k, val := range x {
+					scanString(k, depth)
+					walk(val, depth)
+				}
+			case []any:
+				for _, val := range x {
+					walk(val, depth)
+				}
+			case string:
+				scanString(x, depth)
+			}
+		}
