 374	func (r *oq3Run) terminalStartWithoutCapability(i int, st oq3Step, preloaded func() bool) {
 375		reported := func() bool { return r.term.screenContainsJoined(oq3NoAdmissionVersion) }
 376		if !oq3WaitFor(30*time.Second, func() bool { return preloaded() || r.term.hasExited() || reported() }) {
 377			r.harnessFail("terminal session neither preloaded, reported the missing capability nor exited; screen tail %q", tail(r.term.screen(), 1500))
 378		}
 379		// A report is often the last thing a refusing process prints before it exits.
 380		if reported() && !r.term.hasExited() {
 381			oq3WaitFor(2*time.Second, r.term.hasExited)
 382		}
 383		exitedWithReport := func() {
 384			// The output of a process that has just exited may still be draining from the terminal.
 385			if !oq3WaitFor(3*time.Second, reported) {
 386				r.harnessFail("terminal session exited at start-up without reporting the daemon's version %s; screen tail %q", oq3NoAdmissionVersion, tail(r.term.screen(), 1500))
 387			}
 388			r.termRefusedAtStart = true
 389			r.event(i, st, "refused-at-start", map[string]any{"session": r.termN, "exited": true, "preloaded": preloaded(), "screen_tail": tail(r.term.screen(), 600)})
 390		}
 391		if r.term.hasExited() {
 392			exitedWithReport()
 393			return
 394		}
 395		// Still running: whether it preloaded or reported first, it must reach an idle chat, which also
 396		// settles any preload that follows a report.
 397		if !r.term.idle(30 * time.Second) {
 398			if r.term.hasExited() {
 399				exitedWithReport()
 400				return
 401			}
 402			r.harnessFail("terminal never proved idle after the session started without the capability; screen tail %q", tail(r.term.screen(), 800))
 403		}
 404		if !preloaded() && reported() {
 405			r.termRefusedAtStart = true
 406			r.event(i, st, "refused-at-start", map[string]any{"session": r.termN, "exited": false, "screen_tail": tail(r.term.screen(), 600)})
 407			return
 408		}
 409		r.event(i, st, "done", map[string]any{"session": r.termN, "preloaded": preloaded(), "reported": reported()})
 410	}
